<template><view :class="['app-page',{dark}]"><ui-header title="实名认证" back/><view class="identity-hero"><view><ui-icon name="id-card" :size="58" tone="brand"/></view><text>实名认证保护账户与交易安全</text></view><view v-if="state.status!=='unsubmitted'" class="status-card"><text class="identity-title">{{statusLabel}}</text><text>{{state.realName||''}} {{state.idNumber||''}}</text><text v-if="state.reviewNote" class="error">{{state.reviewNote}}</text><text class="muted">{{state.status==='rejected'?'您可以修正资料后重新提交':'审核状态以后台结果为准'}}</text></view><view v-if="canSubmit" class="form-card"><text class="identity-title">{{state.status==='rejected'?'重新提交认证信息':'请填写实名认证信息'}}</text><view class="form-row"><text class="form-label">真实姓名</text><input v-model="name" class="form-input" placeholder="请填写真实姓名"/></view><view class="form-row"><text class="form-label">证件类型</text><text class="form-input">身份证</text></view><view class="form-row"><text class="form-label">身份证号</text><input v-model="idNumber" class="form-input" placeholder="请填写身份证号"/></view></view><view class="tips"><text class="tip-title">温馨提示</text><text>1. 实名信息需真实有效，存在虚假信息将封禁账号。</text><text>2. 实名一旦认证，将不可更改。</text><text>3. 信息提交后由工作人员人工审核，可在本页查看审核进度和驳回原因。</text></view><text v-if="error" class="error">{{error}}</text><view v-if="canSubmit" class="primary-btn submit" @tap="submit">提交</view></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';
import {confirmSensitiveConsent,SENSITIVE_CONSENT_VERSION} from '@/services/sensitive-consent'
export default{data(){return{dark:false,name:'',idNumber:'',error:'',submitting:false,state:{status:'unsubmitted',canSubmit:true}}},computed:{canSubmit(){return this.state.status==='unsubmitted'||!!this.state.canSubmit},statusLabel(){return({pending:'实名认证审核中',approved:'实名认证已通过',rejected:'实名认证未通过'})[this.state.status]||'实名认证'}},onLoad(){this.dark=isDark();this.load()},methods:{async load(){try{this.state=await api.getIdentity()}catch(e){this.error=e.message||'认证状态加载失败'}},async submit(){if(this.submitting||!this.canSubmit)return;if(!this.name||!/^[1-9]\d{5}(18|19|20)\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])\d{3}[0-9Xx]$/.test(this.idNumber)){this.error='请填写正确的姓名和身份证号';return}this.submitting=true;try{if(!await confirmSensitiveConsent('identity')){this.error='未同意处理身份信息，本次未提交';return}await api.submitIdentity({name:this.name,idNumber:this.idNumber,sensitiveConsent:true,sensitiveConsentVersion:SENSITIVE_CONSENT_VERSION});await this.load();this.name='';this.idNumber='';uni.showToast({title:'已提交审核'})}catch(e){this.error=e.message||'提交失败'}finally{this.submitting=false}}}}</script>
<style scoped>.identity-hero{margin:24rpx 28rpx;padding:26rpx;display:flex;align-items:center;gap:18rpx;border-radius:24rpx;background:linear-gradient(135deg,#eef2ff,#f7f3ff);color:var(--text-secondary);font-size:24rpx}.identity-hero>view{width:80rpx;height:80rpx;display:flex;align-items:center;justify-content:center;border-radius:26rpx;background:#fff}.identity-title{display:block;padding:28rpx 0;font-weight:700}.status-card{margin:24rpx 28rpx;padding:0 28rpx 28rpx;display:flex;flex-direction:column;gap:12rpx;border-radius:24rpx;background:var(--surface);box-shadow:var(--shadow-card)}.status-card .error{margin:0}.tips{margin:0 28rpx;padding:24rpx;display:flex;flex-direction:column;gap:14rpx;border-radius:22rpx;background:var(--surface);color:var(--muted);font-size:24rpx;line-height:37rpx;box-shadow:var(--shadow-card)}.tip-title{color:var(--text);font-weight:700}.error{display:block;margin:20rpx 56rpx;color:var(--primary);font-size:23rpx}.submit{margin:40rpx 78rpx}</style>
